import javax.tools.*;import com.sun.source.util.*;import java.nio.file.*;import java.util.*;
public class ParseJava {public static void main(String[] a)throws Exception{var compiler=ToolProvider.getSystemJavaCompiler();var ds=new DiagnosticCollector<JavaFileObject>();try(var fm=compiler.getStandardFileManager(ds,null,null)){var paths=Files.walk(Path.of(a[0])).filter(p->p.toString().endsWith(".java")).map(Path::toFile).toList();var task=(JavacTask)compiler.getTask(null,fm,ds,List.of("-proc:none"),null,fm.getJavaFileObjectsFromFiles(paths));task.parse();long n=ds.getDiagnostics().stream().filter(d->d.getKind()==Diagnostic.Kind.ERROR).count();ds.getDiagnostics().forEach(System.out::println);System.out.println("Parsed "+paths.size()+" Java files; syntax errors="+n);if(n>0)System.exit(1);}}}
